/// Returns `true` if and only if `n` is a prime number in the range of 8-bit signed integers.
/// By definition, a prime is an integer ≥ 2 that has no positive divisors other than 1 and itself.
fn is_prime(n: i8) -> bool {
    // Handle all cases below 2 right away.
    if n < 2 {
        return false;
    }

    // Try every potential divisor from 2 up to (but not including) n.
    let mut d: i8 = 2;
    while d < n {
        // If `d` divides `n` evenly, `n` is not prime.
        if n % d == 0 {
            return false;
        }
        d += 1;
    }

    // If no divisor was found, `n` is prime.
    true
}

